    descriptionAdvanced: {
      de: "Der Hafen von Sidon (Saida) ist der drittgrößte Hafen des Libanon und von erheblicher historischer sowie lokaler wirtschaftlicher Bedeutung für den Süden des Landes. Während er in der Antike ein florierendes Zentrum des phönizischen Handels war, konzentrieren sich die heutigen wirtschaftlichen Aktivitäten primär auf die lokale Fischereiindustrie, den Küstenhandel und den Import von Schüttgütern. Eine bemerkenswerte Besonderheit des Hafens ist seine Funktion beim Import von Treibstoff und petrochemischen Produkten, die für den Betrieb südlibanesischer Kraftwerke und Industrieanlagen unerlässlich sind. In den letzten Jahrzehnten gab es verschiedene Ausbaupläne, um die Kapazität für den Frachtverkehr zu erhöhen und neue Kaimauern für kommerzielle Schiffe zu errichten. Trotz begrenzter Tiefe, die das Anlegen von großen Containerschiffen verhindert, bleibt der Hafen ein entscheidender Wirtschaftsfaktor für die Region Süd-Libanon und unterstützt den Lebensunterhalt zahlreicher Familien durch Fischfang und begleitende Logistikdienstleistungen.",
      hu: "A szidóni (Szaida) kikötő Libanon harmadik legnagyobb kikötője, és jelentős történelmi, valamint helyi gazdasági fontossággal bír az ország déli részén. Míg az ókorban a föníciai kereskedelem virágzó központja volt, a mai gazdasági tevékenységek elsősorban a helyi halászati iparra, a part menti kereskedelemre és az ömlesztett áruk importjára összpontosítanak. A kikötő egyik figyelemre méltó sajátossága, hogy szerepet játszik az üzemanyagok és petrolkémiai termékek importjában, amelyek elengedhetetlenek a dél-libanoni erőművek és ipari létesítmények működéséhez. Az elmúlt évtizedekben számos bővítési terv született a teherforgalmi kapacitás növelése és a kereskedelmi hajók számára új rakpartfalak építése céljából. A korlátozott vízmélység ellenére, amely megakadályozza a nagy konténerszállító hajók kikötését, a kikötő továbbra is döntő gazdasági tényező a dél-libanoni régió számára, és számos család megélhetését támogatja a halászat és az ahhoz kapcsolódó logisztikai szolgáltatások révén.",
      ro: "Portul Sidon (Saida) este al treilea port ca mărime din Liban și are o importanță istorică și economică locală substanțială pentru sudul țării. În timp ce în antichitate a fost un centru înfloritor al comerțului fenician, activitățile economice de astăzi se concentrează în principal pe industria locală a pescuitului, comerțul de coastă și importul de mărfuri în vrac. O caracteristică notabilă a portului este funcția sa în importul de combustibil și produse petrochimice, care sunt esențiale pentru funcționarea centralelor electrice și a instalațiilor industriale din sudul Libanului. În ultimele decenii, au existat diverse planuri de extindere pentru a crește capacitatea de transport de marfă și pentru a construi noi cheiuri pentru navele comerciale. În ciuda adâncimii limitate care împiedică andocarea navelor mari de containere, portul rămâne un factor economic crucial pentru regiunea sudului Libanului, susținând mijloacele de trai ale numeroaselor familii prin pescuit și servicii logistice asociate.",
      en: "The Port of Sidon (Saida) is the third-largest port in Lebanon and holds substantial historical and local economic importance for the south of the country. While it was a flourishing center of Phoenician trade in antiquity, today's economic activities primarily focus on the local fishing industry, coastal trade, and the import of bulk goods. A notable feature of the port is its function in the import of fuel and petrochemical products, which are essential for the operation of southern Lebanese power plants and industrial facilities. Over the past decades, there have been various expansion plans aimed at increasing freight capacity and constructing new quay walls for commercial vessels. Despite its limited depth, which prevents the docking of large container ships, the port remains a crucial economic driver for the South Lebanon region, supporting the livelihoods of numerous families through fishing and associated logistics services.",
      es: "El puerto de Sidón (Saida) es el tercero más grande del Líbano y posee una importancia económica local significativa para el sur del país. Si bien en la antigüedad fue un próspero centro del comercio fenicio, las actividades actuales se centran en la industria pesquera local, el comercio de cabotaje y la importación de graneles. Una característica notable es su función en la importación de combustible y productos petroquímicos esenciales para el funcionamiento de las centrales eléctricas e instalaciones industriales del sur. En las últimas décadas, ha habido planes de expansión para aumentar la capacidad de carga y construir nuevos muelles comerciales. A pesar de su profundidad limitada, que impide el atraque de grandes portacontenedores, el puerto sigue siendo un factor económico crucial para la región, sustentando a numerosas familias a través de la pesca y los servicios logísticos asociados.",
      pt: "O porto de Sídon (Saida) é o terceiro maior porto do Líbano e possui uma importância económica local significativa para o sul do país. Embora na antiguidade tenha sido um centro florescente do comércio fenício, as atividades atuais centram-se na indústria pesqueira local, no comércio costeiro e na importação de granéis. Uma característica notável é a sua função na importação de combustível e produtos petroquímicos essenciais para o funcionamento das centrais elétricas e instalações industriais do sul. Nas últimas décadas, houve vários planos de expansão para aumentar a capacidade de carga e construir novas muralhas de cais comerciais. Apesar da profundidade limitada, que impede a atracagem de grandes porta-contentores, o porto continua a ser um fator económico crucial para a região, sustentando inúmeras famílias através da pesca e serviços logísticos associados.",
      fr: "Le port de Saïda est le troisième plus grand port du Liban et revêt une importance économique locale considérable pour le sud du pays. Alors qu'il était un centre florissant du commerce phénicien dans l'Antiquité, les activités économiques actuelles se concentrent principalement sur la pêche locale, le commerce côtier et l'importation de vrac. Une caractéristique notable du port est son rôle dans l'importation de carburant et de produits pétrochimiques, essentiels au fonctionnement des centrales électriques et des installations industrielles du Sud-Liban. Au cours des dernières décennies, divers plans d'extension ont été élaborés pour accroître la capacité de fret et construire de nouveaux quais commerciaux. Malgré une profondeur limitée empêchant l'accostage des grands porte-conteneurs, le port reste un facteur économique crucial pour la région.",
    },
