      hu: ["A harmadik legfontosabb kikötő Bejrút és Tripoli után.", "A libanoni halászati ipar központi csomópontja.", "Kulcsszerepet játszik a déli üzemanyag-importban.", "A korlátozott vízmélység behatárolja a hajók méretét.", "Folyamatban lévő projektek a kereskedelmi rakpartok bővítésére.", "A történelmi jelentőséget ötvözi a modern helyi logisztikával."],
