      en: ["Third most important port after Beirut and Tripoli.", "Central hub for the Lebanese fishing industry.", "Key role in the import of fuels into the southern region.", "Limited water depth restricts the maximum ship size.", "Ongoing projects for the expansion of commercial quays.", "Combines historical significance with modern local logistics."],
