      ro: ["Una dintre cele mai importante surse de alimentare cu energie electrică a Beirutului.", "Funcționează în principal cu păcură grea, poluantă.", "Adesea în centrul discuțiilor naționale privind mediul.", "Suferă de o lipsă cronică de întreținere și ineficiență.", "Un reper industrial distinctiv pe coastă.", "Conversia la funcționarea pe gaz a fost întârziată sever."],
      en: ["One of the most important sources of electricity for Beirut.", "Primarily operated with environmentally harmful heavy fuel oil.", "Frequently at the center of nationwide environmental discussions.", "Suffers from chronic lack of maintenance and inefficiency.", "A distinctive industrial landmark on the coast.", "Conversion to gas operation has been severely delayed."],
      es: ["Una de las fuentes más importantes para el suministro eléctrico de Beirut.", "Funciona principalmente con fuel pesado perjudicial para el medio ambiente.", "Frecuentemente en el centro de debates ambientales nacionales.", "Sufre de falta de mantenimiento crónico e ineficiencia.", "Punto de referencia industrial distintivo en la costa.", "La conversión a gas se ha retrasado significativamente hasta ahora."],
      pt: ["Uma das fontes mais importantes para o fornecimento de eletricidade em Beirute.", "Operada principalmente com óleo combustível pesado poluente.", "Frequentemente foco de discussões ambientais nacionais.", "Sofre de falta de manutenção crónica e ineficiência.", "Marco industrial distintivo na costa.", "Conversão para operação a gás fortemente atrasada até agora."],
      fr: ["L'une des sources les plus importantes pour l'alimentation électrique de Beyrouth.", "Fonctionne principalement au fioul lourd polluant.", "Souvent au centre des débats environnementaux nationaux.", "Souffre d'un manque chronique de maintenance et d'inefficacité.", "Repère industriel distinctif sur la côte.", "Conversion au gaz fortement retardée jusqu'à présent."],
