      ro: ["Oferă stimulente fiscale extinse companiilor internaționale.", "Centru pentru importul și exportul de produse farmaceutice și high-tech.", "Generează venituri semnificative în valută prin servicii duty-free.", "Asigură sute de locuri de muncă calificate în zona metropolitană Beirut.", "Foarte securizat și conectat la cele mai moderne lanțuri logistice globale.", "Stabilizează economia de export a Libanului în perioade de criză."],
      en: ["Offers extensive tax incentives for international companies.", "Hub for the import and export of high-tech and pharmaceutical products.", "Generates significant foreign exchange revenues through duty-free services.", "Secures hundreds of skilled jobs in the Greater Beirut area.", "Highly secured and connected to state-of-the-art global logistics chains.", "Stabilizes the Lebanese export economy during times of crisis."],
      es: ["Ofrece amplios incentivos fiscales para empresas internacionales.", "Centro para la importación y exportación de productos de alta tecnología y farmacéuticos.", "Genera importantes ingresos en divisas a través de servicios libres de impuestos.", "Asegura cientos de empleos cualificados en el área metropolitana de Beirut.", "Altamente asegurado y conectado a las cadenas logísticas globales más modernas.", "Estabiliza la economía exportadora libanesa en tiempos de crisis."],
      pt: ["Oferece amplos incentivos fiscais para empresas internacionais.", "Centro para a importação e exportação de produtos de alta tecnologia e farmacêuticos.", "Gera receitas significativas em divisas através de serviços isentos de direitos.", "Assegura centenas de postos de trabalho qualificados na área metropolitana de Beirute.", "Altamente seguro e ligado às mais modernas cadeias logísticas globais.", "Estabiliza a economia de exportação libanesa em tempos de crise."],
